(()=>{
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const isHome=document.body.dataset.page==='home';
 const veil=document.createElement('div');veil.className='page-veil';veil.setAttribute('aria-hidden','true');veil.textContent='幽';document.body.append(veil);let arriving=false;try{arriving=sessionStorage.getItem('yugen-page-crossing')==='yes';sessionStorage.removeItem('yugen-page-crossing')}catch{}if(arriving&&!reduced){veil.classList.add('arrival');requestAnimationFrame(()=>requestAnimationFrame(()=>veil.classList.add('reveal')));setTimeout(()=>veil.classList.remove('arrival','reveal'),800)}
 let leaving=false;
 document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||a.target==='_blank'||a.hasAttribute('download'))return;const dest=new URL(a.href,location.href);if(dest.origin!==location.origin||dest.pathname===location.pathname||!(/(?:index|tradicoes|anime-manga|lugares|historia|costumes|pessoas|sabores|natureza|caderno|creditos)\.html$/.test(dest.pathname)))return;if(reduced)return;e.preventDefault();if(leaving)return;leaving=true;try{sessionStorage.setItem('yugen-page-crossing','yes')}catch{}veil.classList.add('active');setTimeout(()=>location.assign(dest.href),380)});
 addEventListener('pageshow',()=>{leaving=false;veil.classList.remove('active')});
 function showIntro(force=false){window.YugenEntrance?.open(force)}
 document.querySelectorAll('[data-replay-intro]').forEach(b=>b.addEventListener('click',()=>showIntro(true)));showIntro(new URLSearchParams(location.search).get('entrada')==='1');
 if(!reduced&&'IntersectionObserver' in window){const items=document.querySelectorAll('.portal-link,.chapter-lede,.ritual-chapter,.mood-options,.manga-lab .section-heading,.comic-panel,.anime-notes>div,.station-line,.observation-grid article,.next-chapter h2');const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in-view');observer.unobserve(entry.target)}})},{threshold:.08});items.forEach((el,i)=>{el.classList.add('motion-reveal');if(el.matches('.observation-grid article'))el.style.setProperty('--reveal-delay',(i%3)*90+'ms');observer.observe(el)})}
 const parallax=[...document.querySelectorAll('[data-parallax]')];const homeArt=isHome?document.querySelector('.hero-art'):null;const poem=document.querySelector('.scroll-poem');let queued=false;
 function updateScroll(){queued=false;const h=document.documentElement.scrollHeight-innerHeight;const progress=document.getElementById('progress');if(progress)progress.style.width=(h>0?scrollY/h*100:0)+'%';if(!reduced){parallax.forEach(el=>{const r=el.parentElement.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight)el.style.transform='translate3d(0,'+(-r.top*Number(el.dataset.parallax))+'px,0)'});if(homeArt&&scrollY<innerHeight*1.5)homeArt.style.transform='translate3d(0,'+Math.min(scrollY*.16,150)+'px,0) scale(1.025)';if(poem){const r=poem.getBoundingClientRect();const p=Math.max(0,Math.min(1,(-r.top+innerHeight*.2)/(r.height-innerHeight*.6)));poem.style.setProperty('--poem-progress',(p*100)+'%')}}}
 addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(updateScroll)}},{passive:true});addEventListener('resize',updateScroll);updateScroll();
 if(isHome&&'IntersectionObserver' in window){const sections=[['capitulos','Portais'],['universos','Universos'],['rituais','Tradições'],['travessia','Dois ritmos'],['pop','Imaginações'],['estacoes','Estações'],['percurso','Seu caderno']];const rail=document.createElement('nav');rail.className='scroll-chapter-nav';rail.setAttribute('aria-label','Percorrer seções');sections.forEach(([id,label])=>{const a=document.createElement('a');a.href='#'+id;a.setAttribute('aria-label',label==='Portails'?'Portais':label);a.innerHTML='<span>'+(label==='Portails'?'Portais':label)+'</span>';rail.append(a)});document.body.append(rail);const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){rail.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+entry.target.id))}}),{rootMargin:'-25% 0px -50% 0px'});sections.forEach(([id])=>{const el=document.getElementById(id);if(el)observer.observe(el)})}
})();
